// TrapDoorTile.cpp
void TrapDoorTile::setShape(int data)
{

	float r = 3 / 16.0f;
	Tile::setShape(0, 0, 0, 1, r, 1);
	if (isOpen(data))
	{
		if ((data & 3) == 0) setShape(0, 0, 1 - r, 1, 1, 1);
		if ((data & 3) == 1) setShape(0, 0, 0, 1, 1, r);
		if ((data & 3) == 2) setShape(1 - r, 0, 0, 1, 1, 1);
		if ((data & 3) == 3) setShape(0, 0, 0, r, 1, 1);
	}
}

