// PistonExtensionTile.cpp
void PistonExtensionTile::updateShape(LevelSource *level, int x, int y, int z, int forceData, shared_ptr<TileEntity> forceEntity) // 4J added forceData, forceEntity param
{
    int data = (forceData == -1 ) ? level->getData(x, y, z) : forceData;

    const float thickness = PistonBaseTile::PLATFORM_THICKNESS / 16.0f;

    switch (getFacing(data))
	{
		case Facing::DOWN:
			setShape(0, 0, 0, 1, thickness, 1);
			break;
		case Facing::UP:
			setShape(0, 1 - thickness, 0, 1, 1, 1);
			break;
		case Facing::NORTH:
			setShape(0, 0, 0, 1, 1, thickness);
			break;
		case Facing::SOUTH:
			setShape(0, 0, 1 - thickness, 1, 1, 1);
			break;
		case Facing::WEST:
			setShape(0, 0, 0, thickness, 1, 1);
			break;
		case Facing::EAST:
			setShape(1 - thickness, 0, 0, 1, 1, 1);
			break;
    }
}

// PistonExtensionTile.cpp
void PistonExtensionTile::neighborChanged(Level *level, int x, int y, int z, int type)
{
    int facing = getFacing(level->getData(x, y, z));
    int tile = level->getTile(x - Facing::STEP_X[facing], y - Facing::STEP_Y[facing], z - Facing::STEP_Z[facing]);
    if (tile != Tile::pistonBase_Id && tile != Tile::pistonStickyBase_Id)
	{
        level->setTile(x, y, z, 0);
    }
    else
	{
        Tile::tiles[tile]->neighborChanged(level, x - Facing::STEP_X[facing], y - Facing::STEP_Y[facing], z - Facing::STEP_Z[facing], type);
    }
}

// PistonExtensionTile.cpp
int PistonExtensionTile::getFacing(int data)
{
	return data & 0x7;
}

// PistonExtensionTile.cpp
void PistonExtensionTile::addAABBs(Level *level, int x, int y, int z, AABB *box, AABBList *boxes, shared_ptr<Entity> source)
{
    int data = level->getData(x, y, z);

    const float thickness = PistonBaseTile::PLATFORM_THICKNESS / 16.0f;
    const float smallEdge1 = (8.0f - (PistonBaseTile::PLATFORM_THICKNESS / 2.0f)) / 16.0f;
    const float smallEdge2 = (8.0f + (PistonBaseTile::PLATFORM_THICKNESS / 2.0f)) / 16.0f;
    const float largeEdge1 = (8.0f - PistonBaseTile::PLATFORM_THICKNESS) / 16.0f;
    const float largeEdge2 = (8.0f + PistonBaseTile::PLATFORM_THICKNESS) / 16.0f;

    switch (getFacing(data))
	{
		case Facing::DOWN:
			setShape(0, 0, 0, 1, thickness, 1);
			Tile::addAABBs(level, x, y, z, box, boxes, source);
			setShape(smallEdge1, thickness, smallEdge1, smallEdge2, 1, smallEdge2);
			Tile::addAABBs(level, x, y, z, box, boxes, source);
			break;
		case Facing::UP:
			setShape(0, 1 - thickness, 0, 1, 1, 1);
			Tile::addAABBs(level, x, y, z, box, boxes, source);
			setShape(smallEdge1, 0, smallEdge1, smallEdge2, 1 - thickness, smallEdge2);
			Tile::addAABBs(level, x, y, z, box, boxes, source);
			break;
		case Facing::NORTH:
			setShape(0, 0, 0, 1, 1, thickness);
			Tile::addAABBs(level, x, y, z, box, boxes, source);
			setShape(largeEdge1, smallEdge1, thickness, largeEdge2, smallEdge2, 1);
			Tile::addAABBs(level, x, y, z, box, boxes, source);
			break;
		case Facing::SOUTH:
			setShape(0, 0, 1 - thickness, 1, 1, 1);
			Tile::addAABBs(level, x, y, z, box, boxes, source);
			setShape(largeEdge1, smallEdge1, 0, largeEdge2, smallEdge2, 1 - thickness);
			Tile::addAABBs(level, x, y, z, box, boxes, source);
			break;
		case Facing::WEST:
			setShape(0, 0, 0, thickness, 1, 1);
			Tile::addAABBs(level, x, y, z, box, boxes, source);
			setShape(smallEdge1, largeEdge1, thickness, smallEdge2, largeEdge2, 1);
			Tile::addAABBs(level, x, y, z, box, boxes, source);
			break;
		case Facing::EAST:
			setShape(1 - thickness, 0, 0, 1, 1, 1);
			Tile::addAABBs(level, x, y, z, box, boxes, source);
			setShape(0, smallEdge1, largeEdge1, 1 - thickness, smallEdge2, largeEdge2);
			Tile::addAABBs(level, x, y, z, box, boxes, source);
			break;
    }
    setShape(0, 0, 0, 1, 1, 1);

}

// Tile.cpp
float Tile::getExplosionResistance(shared_ptr<Entity> source)
{
	return explosionResistance / 5.0f;
}

// Level.cpp
float Level::getSeenPercent(Vec3 *center, AABB *bb)
{
	double xs = 1.0 / ((bb->x1 - bb->x0) * 2 + 1);
	double ys = 1.0 / ((bb->y1 - bb->y0) * 2 + 1);
	double zs = 1.0 / ((bb->z1 - bb->z0) * 2 + 1);
	int hits = 0;
	int count = 0;
	for (double xx = 0; xx <= 1; xx += xs) // 4J Stu - xx, yy and zz were floats, made them doubles to remove warnings
		for (double yy = 0; yy <= 1; yy += ys)
			for (double zz = 0; zz <= 1; zz += zs)
			{
				double x = bb->x0 + (bb->x1 - bb->x0) * xx;
				double y = bb->y0 + (bb->y1 - bb->y0) * yy;
				double z = bb->z0 + (bb->z1 - bb->z0) * zz;
				HitResult *res = clip(Vec3::newTemp(x, y, z), center);
				if ( res == NULL) hits++;
				delete res;
				count++;
			}

	return hits / (float) count;
}

// TntTile.cpp
void TntTile::onPlace(Level *level, int x, int y, int z)
{
	Tile::onPlace(level, x, y, z);
    if (level->hasNeighborSignal(x, y, z) && app.GetGameHostOption(eGameHostOption_TNT))
	{
        destroy(level, x, y, z, EXPLODE_BIT);
        level->setTile(x, y, z, 0);
    }
}

// TntTile.cpp
void TntTile::neighborChanged(Level *level, int x, int y, int z, int type)
{
	if (type > 0 && Tile::tiles[type]->isSignalSource())
	{
		if (level->hasNeighborSignal(x, y, z) && app.GetGameHostOption(eGameHostOption_TNT))
		{
			destroy(level, x, y, z, EXPLODE_BIT);
			level->setTile(x, y, z, 0);
		}
	}
}

// TntTile.cpp
void TntTile::wasExploded(Level *level, int x, int y, int z)
{
	// 4J - added - don't every create on the client, I think this must be the cause of a bug reported in the java
	// version where white tnts are created in the network game
	if (level->isClientSide) return;	

	// 4J - added condition to have finite limit of these
	// 4J-JEV: Fix for #90934 - Customer Encountered: TU11: Content: Gameplay: TNT blocks are triggered by explosions even though "TNT explodes" option is unchecked.
	if( level->newPrimedTntAllowed() && app.GetGameHostOption(eGameHostOption_TNT) )
	{
		shared_ptr<PrimedTnt> primed = shared_ptr<PrimedTnt>( new PrimedTnt(level, x + 0.5f, y + 0.5f, z + 0.5f) );
		primed->life = level->random->nextInt(primed->life / 4) + primed->life / 8;
		level->addEntity(primed);
	}
}

// TntTile.cpp
void TntTile::destroy(Level *level, int x, int y, int z, int data)
{
	if (level->isClientSide) return;

	if ((data & EXPLODE_BIT) == 1 )
	{
		// 4J - added condition to have finite limit of these
		if( level->newPrimedTntAllowed() && app.GetGameHostOption(eGameHostOption_TNT) )
		{
			shared_ptr<PrimedTnt> tnt = shared_ptr<PrimedTnt>(  new PrimedTnt(level, x + 0.5f, y + 0.5f, z + 0.5f) );
			level->addEntity(tnt);
			level->playSound(tnt, eSoundType_RANDOM_FUSE, 1, 1.0f);
		}
	}
}

// TntTile.cpp
bool TntTile::use(Level *level, int x, int y, int z, shared_ptr<Player> player, int clickedFace, float clickX, float clickY, float clickZ, bool soundOnly/*=false*/) // 4J added soundOnly param
{
	if (soundOnly) return false;
	if (player->getSelectedItem() != NULL && player->getSelectedItem()->id == Item::flintAndSteel_Id)
	{
		destroy(level, x, y, z, EXPLODE_BIT);
		level->setTile(x, y, z, 0);
		return true;
	}
	return Tile::use(level, x, y, z, player, clickedFace, clickX, clickY, clickZ);
}

// Explosion.cpp
Explosion::Explosion(Level *level, shared_ptr<Entity> source, double x, double y, double z, float r)
{
	fire = false;
	random = new Random();

	this->level = level;
	this->source = source;
	this->r = r;
	this->x = x;
	this->y = y;
	this->z = z;

	destroyBlocks = true;
	size = 16;
}

// Explosion.cpp
Explosion::~Explosion()
{
	delete random;
	for(AUTO_VAR(it, hitPlayers.begin()); it != hitPlayers.end(); ++it)
	{
		delete it->second;
	}
}

// Explosion.cpp
void Explosion::explode()
{
	float oR = r;

	int size = 16;
	for (int xx = 0; xx < size; xx++)
	{
		for (int yy = 0; yy < size; yy++)
		{
			for (int zz = 0; zz < size; zz++)
			{
				if ((xx != 0 && xx != size - 1) && (yy != 0 && yy != size - 1) && (zz != 0 && zz != size - 1)) continue;

				double xd = xx / (size - 1.0f) * 2 - 1;
				double yd = yy / (size - 1.0f) * 2 - 1;
				double zd = zz / (size - 1.0f) * 2 - 1;
				double d = sqrt(xd * xd + yd * yd + zd * zd);

				xd /= d;
				yd /= d;
				zd /= d;

				float remainingPower = r * (0.7f + level->random->nextFloat() * 0.6f);
				double xp = x;
				double yp = y;
				double zp = z;

				float stepSize = 0.3f;
				while (remainingPower > 0)
				{
					int xt = Mth::floor(xp);
					int yt = Mth::floor(yp);
					int zt = Mth::floor(zp);
					int t = level->getTile(xt, yt, zt);
					if (t > 0)
					{
						remainingPower -= (Tile::tiles[t]->getExplosionResistance(source) + 0.3f) * stepSize;
					}
					if (remainingPower > 0)
					{
						toBlow.insert(TilePos(xt, yt, zt));
					}

					xp += xd * stepSize;
					yp += yd * stepSize;
					zp += zd * stepSize;
					remainingPower -= stepSize * 0.75f;
				}
				// if (xd*xd+yd*yd+zd*zd>1) continue;
			}
		}
	}

	r *= 2.0f;
	int x0 = Mth::floor(x - r - 1);
	int x1 = Mth::floor(x + r + 1);
	int y0 = Mth::floor(y - r - 1);
	int y1 = Mth::floor(y + r + 1);
	int z0 = Mth::floor(z - r - 1);
	int z1 = Mth::floor(z + r + 1);

	// Fix for 360 #123866 - [CRASH] TU13: Code: Compliance: Placing the TNT next to Ender Crystals will crash the title after a certain amount of time.
	// If we explode something next to an EnderCrystal then it creates a new explosion that overwrites the shared vector in the level
	// So copy it here instead of directly using the shared one
	vector<shared_ptr<Entity> > *levelEntities = level->getEntities(source, AABB::newTemp(x0, y0, z0, x1, y1, z1));
	vector<shared_ptr<Entity> > entities(levelEntities->begin(), levelEntities->end() );
	Vec3 *center = Vec3::newTemp(x, y, z);

	AUTO_VAR(itEnd, entities.end());
	for (AUTO_VAR(it, entities.begin()); it != itEnd; it++)
	{
		shared_ptr<Entity> e = *it; //entities->at(i);

		// 4J Stu - If the entity is not in a block that would be blown up, then they should not be damaged
		// Fix for #46606 - TU5: Content: Gameplay: The player can be damaged and killed by explosions behind obsidian walls
		bool canDamage = false;
		for(AUTO_VAR(it2, toBlow.begin()); it2 != toBlow.end(); ++it2)
		{
			if(e->bb->intersects(it2->x,it2->y,it2->z,it2->x + 1,it2->y + 1,it2->z + 1))
			{
				canDamage = true;
				break;
			}
		}

		double dist = e->distanceTo(x, y, z) / r;
		if (dist <= 1)
		{
			double xa = e->x - x;
			double ya = e->y + e->getHeadHeight() - y;
			double za = e->z - z;

			double da = sqrt(xa * xa + ya * ya + za * za);

			// 4J Stu - Added this check to remove divide by zero errors (or rather the issues caused by
			// the values being set to NaN and used in comparisons a bit later on e.g. fireball)
			if( da == 0 )
			{
				xa = ya = za = 0.0;
			}
			else
			{
				xa /= da;
				ya /= da;
				za /= da;
			}

			double sp = level->getSeenPercent(center, e->bb);
			double pow = (1 - dist) * sp;
			if(canDamage) e->hurt(DamageSource::explosion, (int) ((pow * pow + pow) / 2 * 8 * r + 1));

			double push = pow;
			e->xd += xa * push;
			e->yd += ya * push;
			e->zd += za * push;					

			shared_ptr<Player> player = dynamic_pointer_cast<Player>(e);
			if (player != NULL)
			{
				//app.DebugPrintf("Adding player knockback (%f,%f,%f)\n", xa * pow, ya * pow, za * pow);
				hitPlayers.insert( playerVec3Map::value_type( player, Vec3::newPermanent(xa * pow, ya * pow, za * pow)));
			}
		}
	}
	r = oR;
}

// Explosion.cpp
void Explosion::finalizeExplosion(bool generateParticles, vector<TilePos> *toBlowDirect/*=NULL*/)		// 4J - added toBlowDirect parameter
{
	level->playSound(x, y, z, eSoundType_RANDOM_EXPLODE, 4, (1 + (level->random->nextFloat() - level->random->nextFloat()) * 0.2f) * 0.7f);
	level->addParticle(eParticleType_hugeexplosion, x, y, z, 0, 0, 0);

	// 4J - use pointer to vector directly passed in if this is available - used to speed up calling this from an incoming packet
	vector<TilePos> *toBlowArray = toBlowDirect ? toBlowDirect : new vector<TilePos>( toBlow.begin(), toBlow.end() );
	//toBlowArray.addAll(toBlow);
	// TODO 4J Stu - Reverse iterator
	PIXBeginNamedEvent(0,"Finalizing explosion size %d",toBlow.size());
	app.DebugPrintf("Finalizing explosion size %d\n",toBlow.size());
	static const int MAX_EXPLODE_PARTICLES = 50;
	// 4J - try and make at most MAX_EXPLODE_PARTICLES pairs of particles
	int fraction = (int)toBlowArray->size() / MAX_EXPLODE_PARTICLES;
	if( fraction == 0 ) fraction = 1;
	size_t j = toBlowArray->size() - 1;
	//for (size_t j = toBlowArray->size() - 1; j >= 0; j--)
	for(AUTO_VAR(it,toBlowArray->rbegin()); it != toBlowArray->rend(); ++it)
	{
		TilePos *tp = &(*it); //&toBlowArray->at(j);
		int xt = tp->x;
		int yt = tp->y;
		int zt = tp->z;
		// if (xt >= 0 && yt >= 0 && zt >= 0 && xt < width && yt < depth &&
		// zt < height) {
		int t = level->getTile(xt, yt, zt);

		if (generateParticles)
		{
			if( ( j % fraction ) == 0  )
			{
				double xa = xt + level->random->nextFloat();
				double ya = yt + level->random->nextFloat();
				double za = zt + level->random->nextFloat();

				double xd = xa - x;
				double yd = ya - y;
				double zd = za - z;

				double dd = sqrt(xd * xd + yd * yd + zd * zd);

				xd /= dd;
				yd /= dd;
				zd /= dd;

				double speed = 0.5 / (dd / r + 0.1);
				speed *= (level->random->nextFloat() * level->random->nextFloat() + 0.3f);
				xd *= speed;
				yd *= speed;
				zd *= speed;

				level->addParticle(eParticleType_explode, (xa + x * 1) / 2, (ya + y * 1) / 2, (za + z * 1) / 2, xd, yd, zd);
				level->addParticle(eParticleType_smoke, xa, ya, za, xd, yd, zd);
			}
		}

		if (t > 0)
		{
			Tile::tiles[t]->spawnResources(level, xt, yt, zt, level->getData(xt, yt, zt), 0.3f, 0);
			level->setTile(xt, yt, zt, 0);
			Tile::tiles[t]->wasExploded(level, xt, yt, zt);
		}
		// }

		--j;
	}

	if (fire)
	{
		//for (size_t j = toBlowArray->size() - 1; j >= 0; j--)
		for(AUTO_VAR(it,toBlowArray->rbegin()); it != toBlowArray->rend(); ++it)
		{
			TilePos *tp = &(*it); //&toBlowArray->at(j);
			int xt = tp->x;
			int yt = tp->y;
			int zt = tp->z;
			int t = level->getTile(xt, yt, zt);
			int b = level->getTile(xt, yt - 1, zt);
			if (t == 0 && Tile::solid[b] && random->nextInt(3) == 0)
			{
				level->setTile(xt, yt, zt, Tile::fire_Id);
			}
		}
	}

	PIXEndNamedEvent();
	if( toBlowDirect == NULL )	delete toBlowArray;
}

